      [
        [
          "给不一致留一个公平的核验过程",
          "Give discrepancies a fair review process"
        ],
        [
          "向代理发出针对具体对象的补件请求。写清需要核对的账号、窗口、字段与来源，不要求对方证明「所有人都是真人」这种无法合理完成的命题。规定答复负责人和时间，保留原始提案与修订版本。若问题只是名称错误，修正交接；如果主体仍不清楚，暂停该服务访问；若数据定义变了，重写对应的结论。不同缺口不应共用一个黑名单标签。\n\n复核也要考虑创作者并未选择服务商的情形。品牌或代理增加的工具，不应让创作者承担不明责任。把实际批准人和使用记录查清，再处理合作安排。公开报告中避免写未经证实的归责。内部材料也应只让有任务的人看到。可以拒绝一个不能满足证据标准的提案，同时继续验收已完成、能够独立确认的内容资产。",
          "Send the agency an evidence request tied to the specific account, period, field and source. Do not demand proof that every person is genuine, an assertion the review cannot reasonably establish. Set an owner and response date, and retain both the original proposal and revisions. A naming error needs a corrected handoff. An unidentified provider may require pausing access. A changed metric definition requires a revised conclusion. These are different issues and should not share one blacklist label.\n\nConsider whether the creator chose the service at all. A connection added by a brand or agency should not automatically become the creator’s responsibility. Trace the approval and use record before applying a commercial remedy. Avoid unsupported attribution in a public report, and limit internal access to people with a review task. The buyer can decline a proposal that fails its evidence requirements while separately accepting completed content that can be verified independently. A fair process makes those decisions traceable."
        ],
        []
      ],
      [
        [
          "发生接入事故时保护信息",
          "Protect information if the review reveals an incident"
        ],
        [
          "FTC 的企业信息保护指南建议了解持有的信息、限制保留并计划应对安全事件。若核验发现名单或账号资料已经被发送给未知接收方，先交给负责安全与隐私的人判断处置。活动团队提供必要时间线、数据类别和接收范围，避免把原始客户资料再次复制进群。调查资料的访问应有限定，处理人也要知道哪些证据需要保留。\n\n如果问题涉及登录秘密，由账号所有者通过原生安全渠道处理，不从搜索结果临时找恢复商。营销协调人负责暂停依赖该服务的发布或报告流程，并说明替代负责人。恢复账号、撤销权限和验证增长结果分别记录。不要把「服务已断开」当成历史数据已恢复准确，也不要把一项风险提示写成已经发生数据滥用。事件结论继续遵循可证实的范围。",
          "The FTC’s business information protection guide recommends understanding held information, limiting retention and planning an incident response. If the review finds that a roster or account data already went to an unknown recipient, involve the people responsible for security and privacy. Provide the timeline, information categories and known recipient scope without copying raw customer data into another group. Restrict investigation material and establish what evidence should be retained.\n\nFor exposed authentication secrets, the account owner should use native security routes rather than an improvised recovery supplier found in search. The marketing coordinator pauses publication or reporting that depends on the service and identifies a fallback owner. Record access restoration, permission removal and validation of historical growth as separate work. A disconnected service does not restore the accuracy of earlier metrics. Equally, a risk signal does not establish actual misuse. Keep the incident conclusion within the facts that can be confirmed."
        ],
        [
          "ftcPrivacy"
        ]
      ],
      [
        [
          "给下一位负责人一份可执行的决定",
          "Hand over a decision the next owner can execute"
        ],
        [
          "最终记录四组名称及相互关系、具体服务、授权范围、证据状态与批准人。决定可以是仅允许公开研究、补充资料后再评估，或拒绝任何账号接入。把适用账号、期限与重新审查触发条件写上。后续供应商换域名、增加权限或更改服务机制时，不能自动继承旧结论。\n\n例如品牌确认代理只需人工查公开作品，就可以先让研究继续，把涨粉服务排除在范围之外。若下一步需要邀请合适达人，用候选名单工作流记录作品、相关性与公开联系路径。采购结果由任务与证据决定，不由搜索词的流量决定。这样的交接既能保留可用的研究，也能让未来同事看懂身份核验做到了哪一层，以及尚有什么条件需要实际确认。",
          "Record the four identifiers and their relationship, the exact service, approved scope, evidence status and decision owner. The result might allow public research only, require more information or decline any account connection. Name the accounts, duration and conditions that trigger another review. A new domain, broader permission request or changed mechanism should not inherit an old approval without inspection.\n\nFor example, the brand may establish that the agency only needs manual public-content research. That work can proceed while a follower service remains outside the scope. If the next task is to approach suitable creators, use the creator shortlist workflow to preserve work samples, relevance and public contact routes. Purchasing follows the task and evidence rather than a search phrase’s apparent popularity. The handoff should tell the next colleague what identity checks were completed, what work is allowed and which conditions still need actual confirmation."
        ],
        []
      ],
      [
        [
          "用代理转述案例核对责任链",
          "Trace responsibility through an agency referral"
        ],
        [
          "假设品牌收到代理转发的一张网站截图，代理把展示名当成服务商，创作者却只收到一个短链接。先请代理补齐实际主体与范围，再由账号所有者判断是否授权。不要向创作者索取登录资料来帮助代理完成身份检查。如果代理原来只获准采购作品，增加账号操作也应单独确认。\n\n假设补件后发现网站只提供公开数据查询，原来的「保证涨粉」来自转述错误。把提案和对外说法一起更正，而不是因为身份已查明就继续保留错误效果承诺。相反，如果主体已明确但操作机制仍未知，身份这一列可以完成，效果这一列继续待核验。每列有自己的材料和批准人，结论才不会在多人交接中被不断扩大。保留原始与修订版本，也给后续审阅人公平地解释发生了什么。",
          "Suppose a brand receives a website screenshot forwarded by an agency. The agency treats the displayed name as the provider, while the creator receives only a shortened link. Ask the agency to establish the entity and scope, then let the account owner decide about authorization. Do not request the creator’s credentials to help the agency complete an identity check. If the agency was authorized to buy content only, account operations need their own scope decision.\n\nNow suppose the evidence shows a public research service and the guaranteed growth claim came from an inaccurate summary. Correct both the proposal and any external statement instead of retaining the claim merely because identity is resolved. Conversely, a confirmed entity with an unexplained mechanism can pass one column while performance remains pending. Each column needs its own material and approver so the conclusion does not expand through successive handoffs. Preserve the original and revised versions and explain the correction to anyone relying on the earlier summary. This provides a fair record of the change and makes the next purchase decision easier to trace."
        ],
        []
      ]
