          "If the only established fact is unclear provider wording, the next step may be clarification. An unnecessary permission calls for access review. A report using affected figures calls for annotation and reassessment. Different evidence should not produce the same automatic rejection. Use the creator campaign measurement framework to identify which results should remain outside budget comparisons and which deliverables can still be accepted.\n\nAuthentic production does not become worthless because a distribution question remains unresolved. Accept completed work under the agreement where appropriate while leaving the relevant reporting evidence pending. Payment, additional delivery or termination should follow the contract and proper process rather than an anomaly chart alone. Distinguishing tasks from evidentiary scope makes the action more proportionate. It also allows a later correction to update the affected decision without requiring the team to reverse an unsupported judgment about the creator’s whole body of work."
