          "假设账号在同一周参加品牌联名、获得媒体转发，也收到免费粉丝服务的推销。研究员看到上涨后，不能从三件同期事件中任意选择一个作为原因。先确认推销是否被接受，再记录联名和媒体的可见发布。没有订单或授权证据时，供应商存在只是背景，不等于实际接入。\n\n向创作者询问时，可以说明已观察到的时间窗口并请其补充已知推广，不要求解释每位新关注者。若对方提供正常活动记录，加入时间线并保留还不能确定的部分。品牌内部报告应写资料支持哪些解释、哪些仍待核对。这样的结论可能没有真假标签简短，却更能支持继续合作、补证或暂停特定采购的决定。\n\n下一位负责人应看到原声明与后续记录的区别，不能只收到“有异常”三个字。给问题一个范围和截止复核时间，有助于避免未解决的线索在团队中传播成已经证实的指控。",
          "Suppose an account joins a brand collaboration, receives media coverage and encounters a free-follower sales pitch in the same week. Observing growth does not let the researcher select one of those events as the cause. First establish whether the pitch was accepted, then record the visible collaboration and media publication. Without purchase or authorization evidence, the provider’s presence is background, not proof that a service was connected.\n\nWhen asking the creator, identify the observed period and invite known promotional context rather than demanding an explanation for every new follower. Add legitimate activity records to the timeline while retaining what they cannot establish. The internal report should say which explanations have support and which remain to be checked. That may be longer than an authenticity label, but it better supports a decision to continue, seek evidence or hold a particular purchase.\n\nThe next owner needs to distinguish the original claim from later records instead of receiving only the phrase unusual growth. Give the question a scope and review date. This reduces the chance that an unresolved lead circulates as a proven accusation. It also means the brand can update one interpretation when new evidence arrives without erasing the original observations or pretending that the first review established more than it did."
